{"implementation":"def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    node_dict = {n['id']: n for n in nodes}
    children = {}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children.setdefault(pid, []).append(n['id'])
    retained = set(n['id'] for n in nodes)
    removed = []
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    for n in sorted_nodes:
        nid = n['id']
        if nid not in retained:
            continue
        if not n['removable']:
            continue
        if n['symbol'] in required_symbols:
            continue
        if n['parent'] is None:
            continue
        has_retained_children = False
        for child_id in children.get(nid, []):
            if child_id in retained:
                has_retained_children = True
                break
        if has_retained_children:
            continue
        retained.remove(nid)
        removed.append(nid)
    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removed,
        'retained_node_ids': retained_sorted
    }"}
